begin;
select no_plan();
insert into auth.users(id,email) values ('10000000-0000-4000-8000-000000000001','bill-owner@test.invalid'),('10000000-0000-4000-8000-000000000002','bill-server@test.invalid'),('10000000-0000-4000-8000-000000000003','bill-other@test.invalid');
insert into public.restaurants(id,slug,name) values ('10000000-0000-4000-8000-000000000010','bill-test','Bill test');
insert into public.memberships(restaurant_id,user_id,role) values ('10000000-0000-4000-8000-000000000010','10000000-0000-4000-8000-000000000001','owner'),('10000000-0000-4000-8000-000000000010','10000000-0000-4000-8000-000000000002','server');
insert into public.dining_tables(id,restaurant_id,label) values ('10000000-0000-4000-8000-000000000020','10000000-0000-4000-8000-000000000010','B1');
insert into public.menu_sections(id,restaurant_id,name_es,name_en) values ('10000000-0000-4000-8000-000000000030','10000000-0000-4000-8000-000000000010','Platos','Dishes');
insert into public.menu_items(id,restaurant_id,section_id,name_es,name_en,price_cents) values ('10000000-0000-4000-8000-000000000040','10000000-0000-4000-8000-000000000010','10000000-0000-4000-8000-000000000030','Plato','Dish',1001);
create schema billtest;
grant usage,create on schema billtest to service_role;
create function billtest.tab() returns uuid language sql as $$select id from public.tabs where table_id='10000000-0000-4000-8000-000000000020' and status<>'closed'$$;
create function billtest.pid(n text) returns uuid language sql as $$select id from public.tab_participants where tab_id=billtest.tab() and display_name=n$$;
create function billtest.staff(op text,d jsonb default '{}',actor uuid default '10000000-0000-4000-8000-000000000002') returns jsonb language sql as $$select public.visit_workflow(op,p_tab=>billtest.tab(),p_actor=>actor,p_data=>d)$$;
create function billtest.guest(op text,d jsonb default '{}',h text default repeat('a',64)) returns jsonb language sql as $$select public.visit_workflow(op,p_tab=>billtest.tab(),p_secret_hash=>h,p_data=>d)$$;
create function billtest.split() returns jsonb language plpgsql as $$declare snap jsonb; portions jsonb; begin
 snap=public.visit_snapshot(billtest.tab());
 select jsonb_agg(jsonb_build_object('participantId',pid,'label',name,'subtotalCents',1001,'stateCents',105,'municipalCents',10,'lines',(select jsonb_agg(jsonb_build_object('lineId',x->>'id','unit',0,'name','Plato','cents',case when (rownum%2)=n then 501 else 500 end)) from (select x,row_number() over() rownum from jsonb_array_elements(snap->'lines')x)l))) into portions from (values(billtest.pid('Ana'),'Ana',1),(billtest.pid('Ben'),'Ben',0))p(pid,name,n);
 return jsonb_build_object('revision',snap->'revision','mode','even','ackDrafts',true,'portions',portions);
end $$;
grant execute on all functions in schema billtest to service_role;
select ok(not has_function_privilege('authenticated','public.visit_workflow(text,uuid,uuid,uuid,text,jsonb)','execute'),'browser cannot call privileged workflow');
select ok(not has_schema_privilege('authenticated','mezza_private','usage'),'browser cannot read session hashes or financial allocations');
set local role service_role;
select lives_ok($$select public.visit_workflow('open',p_table=>'10000000-0000-4000-8000-000000000020',p_actor=>'10000000-0000-4000-8000-000000000002')$$,'server opens visit');
select throws_ok($$select public.visit_workflow('open',p_table=>'10000000-0000-4000-8000-000000000020',p_actor=>'10000000-0000-4000-8000-000000000002')$$,'P0001','visit_already_open','no second live visit');
select throws_ok($$select billtest.staff('snapshot','{}','10000000-0000-4000-8000-000000000003')$$,'42501','forbidden','nonmember actor denied');
select lives_ok($$select public.visit_workflow('join',p_tab=>billtest.tab(),p_secret_hash=>repeat('a',64),p_data=>jsonb_build_object('name','Ana','receiptHash',repeat('c',64)))$$,'first guest joins');
select lives_ok($$select public.visit_workflow('join',p_tab=>billtest.tab(),p_secret_hash=>repeat('b',64),p_data=>jsonb_build_object('name','Ben','receiptHash',repeat('d',64)))$$,'second guest joins');
select ok(not (billtest.guest('snapshot')::text like '%secret_hash%'),'group snapshot contains no credentials');
select lives_ok($$select billtest.guest('draft','{"version":0,"lines":[{"itemId":"10000000-0000-4000-8000-000000000040","qty":1,"optionIds":[],"nameEs":"Plato"}]}')$$,'save versioned draft');
select throws_ok($$select billtest.guest('draft','{"version":0,"lines":[]}')$$,'P0001','stale_cart','stale device cannot overwrite newer cart');
select lives_ok($$select billtest.guest('submit','{"id":"10000000-0000-4000-8000-000000000050","version":1}')$$,'submit creates review request');
select is((select count(*)::int from public.orders),0,'unaccepted request does not reach kitchen');
select lives_ok($$select billtest.guest('submit','{"id":"10000000-0000-4000-8000-000000000050","version":1}')$$,'retry submission idempotent');
select is((select count(*)::int from mezza_private.visit_requests),1,'retry makes only one request');
select throws_ok($$select billtest.guest('submit','{"id":"10000000-0000-4000-8000-000000000050","version":1}',repeat('b',64))$$,'42501','forbidden','other participant cannot reuse a request key');
select throws_ok($$select billtest.staff('freeze',jsonb_build_object('revision',0))$$,'P0001','pending_requests','pending requests block checkout');
select lives_ok($$select billtest.staff('accept','{"id":"10000000-0000-4000-8000-000000000050"}')$$,'acceptance creates actual menu-priced kitchen order');
select lives_ok($$select billtest.staff('accept','{"id":"10000000-0000-4000-8000-000000000050"}')$$,'acceptance retry idempotent');
select is((select count(*)::int from public.orders),1,'accepted exactly once');
select is((select unit_price_cents from public.order_items limit 1),1001,'server prices from menu');
select lives_ok($$select billtest.guest('draft','{"version":0,"lines":[{"itemId":"10000000-0000-4000-8000-000000000040","qty":1,"optionIds":[]}]}',repeat('b',64))$$,'independent same dish allowed');
select lives_ok($$select billtest.guest('submit','{"id":"10000000-0000-4000-8000-000000000051","version":1}',repeat('b',64))$$,'second guest submission independent');
select lives_ok($$select billtest.staff('accept','{"id":"10000000-0000-4000-8000-000000000051"}')$$,'accept second identical dish');
select is((select count(*)::int from public.orders),2,'legitimate duplicate dish not deduplicated');
select throws_ok($$select billtest.staff('freeze',billtest.split()||'{"revision":0}')$$,'P0001','stale_bill','stale allocation rejected');
select throws_ok($$select billtest.staff('freeze',jsonb_set(billtest.split(),'{portions,0,lines,0,cents}','999'))$$,'P0001','unit_allocation_mismatch','tampered unit allocation rejected');
select lives_ok($$select billtest.staff('freeze',billtest.split())$$,'freeze exact cents and preserved taxes');
select is((select sum(subtotal_cents+state_cents+municipal_cents)::bigint from mezza_private.bill_portions),2232::bigint,'portions conserve original subtotal and both tax components');
select throws_ok($$select billtest.guest('draft','{"version":2,"lines":[]}')$$,'P0001','invalid_draft','locked cart cannot change');
select throws_ok($$select billtest.guest('request_cancel','{"id":"10000000-0000-4000-8000-000000000050"}')$$,'P0001','bill_locked','locked bill cannot acquire a cancellation race');
select throws_ok($$update public.order_items set qty=2$$,'P0001','bill_locked','legacy staff cannot edit locked charges');
select lives_ok($$update public.order_items set status='served'$$,'kitchen can advance status while locked');
select lives_ok($$select billtest.staff('reopen')$$,'can unlock before any settlement');
select lives_ok($$select billtest.staff('freeze',billtest.split())$$,'can freeze corrected allocation');
select throws_ok($$select billtest.staff('cash',jsonb_build_object('portionIds',(select jsonb_agg(id) from mezza_private.bill_portions),'payerId',billtest.pid('Ana'),'key','cash-test-1','tipCents',0,'tenderCents',100,'receiptHash',repeat('e',64)))$$,'P0001','insufficient_tender','insufficient cash never pays portions');
select is((select count(*)::int from public.payments),0,'failed tender has no payment effects');
select lives_ok($$select billtest.staff('cash',jsonb_build_object('portionIds',(select jsonb_agg(id) from mezza_private.bill_portions),'payerId',billtest.pid('Ana'),'key','cash-test-1','tipCents',0,'tenderCents',2500,'receiptHash',repeat('e',64)))$$,'one payer covers both portions atomically');
select lives_ok($$select billtest.staff('cash',jsonb_build_object('portionIds',(select jsonb_agg(id) from mezza_private.bill_portions),'payerId',billtest.pid('Ana'),'key','cash-test-1','tipCents',0,'tenderCents',2500,'receiptHash',repeat('e',64)))$$,'cash confirmation retry idempotent');
select is((select count(*)::int from public.payments),1,'one payment on retry');
select is((select tip_cents from public.payments limit 1),0,'excess tender is change not tip');
select is((select amount_cents+ivu_state_cents+ivu_municipal_cents from public.payments limit 1),2232,'payment is actual due not tender');
select is(jsonb_array_length(public.visit_private_receipts(repeat('c',64),'10000000-0000-4000-8000-000000000020')),1,'payer can access own receipt');
select is(jsonb_array_length(public.visit_private_receipts(repeat('d',64),'10000000-0000-4000-8000-000000000020')),0,'covered participant cannot access payer payment details');
select throws_ok($$select billtest.staff('reopen')$$,'P0001','cannot_reopen','cannot reopen paid bill');
select throws_ok($$select billtest.staff('cash',jsonb_build_object('portionIds',(select jsonb_agg(id) from mezza_private.bill_portions),'payerId',billtest.pid('Ana'),'key','another-payment','tipCents',0,'tenderCents',2500,'receiptHash',repeat('e',64)))$$,'P0001','portion_already_settled','new key cannot double pay settled portions');
select lives_ok($$select billtest.staff('close')$$,'staff closes fully settled visit');
select ok((select bool_and(revoked_at is not null) from mezza_private.visit_sessions),'close revokes every participant');
select is(jsonb_array_length(public.visit_private_receipts(repeat('c',64),'10000000-0000-4000-8000-000000000020')),1,'closed visit keeps payer-only receipt access');
select ok((select bool_and(expires_at=now()+interval '7 days') from mezza_private.visit_receipts),'receipt expiry exactly seven days after closure');
select lives_ok($$select public.visit_workflow('open',p_table=>'10000000-0000-4000-8000-000000000020',p_actor=>'10000000-0000-4000-8000-000000000002')$$,'next party has a fresh visit');
select throws_ok($$select billtest.guest('snapshot')$$,'42501','session_expired','old phone cannot view next party');
select is(jsonb_array_length(public.visit_snapshot(billtest.tab())->'participants'),0,'new visit has no old people or carts');

select lives_ok($$select public.visit_workflow('join',p_tab=>billtest.tab(),p_secret_hash=>repeat('f',64),p_data=>jsonb_build_object('name','Cam','receiptHash',repeat('1',64)))$$,'new party joins its own visit');
select lives_ok($$select billtest.staff('pause','{"paused":true}')$$,'staff pauses guest ordering');
select lives_ok($$select billtest.guest('draft','{"version":0,"lines":[{"itemId":"10000000-0000-4000-8000-000000000040","qty":1,"optionIds":[]}]}',repeat('f',64))$$,'pause retains draft access');
select throws_ok($$select billtest.guest('submit','{"id":"10000000-0000-4000-8000-000000000070","version":1}',repeat('f',64))$$,'P0001','ordering_paused','pause blocks new submissions');
select lives_ok($$select billtest.guest('request_service','{"kind":"bring_check"}',repeat('f',64))$$,'pause preserves requesting the bill');
select lives_ok($$select billtest.staff('pause','{"paused":false}')$$,'staff resumes ordering');
select lives_ok($$select billtest.staff('recover',jsonb_build_object('participantId',billtest.pid('Cam'),'ticketHash',repeat('2',64)))$$,'staff creates short-lived recovery ticket');
select throws_ok($$select billtest.guest('snapshot','{}',repeat('f',64))$$,'42501','session_expired','recovery immediately revokes old device');
select lives_ok($$select public.visit_claim_recovery(repeat('2',64),'10000000-0000-4000-8000-000000000020',repeat('3',64),repeat('4',64))$$,'verified device recovers same identity');
select throws_ok($$select public.visit_claim_recovery(repeat('2',64),'10000000-0000-4000-8000-000000000020',repeat('5',64),repeat('6',64))$$,'P0001','invalid_recovery','recovery ticket is single use');
select is((select count(*)::int from public.tab_participants where tab_id=billtest.tab()),1,'recovery does not create a duplicate diner');
select lives_ok($$select billtest.staff('remove',jsonb_build_object('participantId',billtest.pid('Cam')))$$,'staff removes participant access');
select throws_ok($$select billtest.guest('snapshot','{}',repeat('3',64))$$,'42501','session_expired','removed participant loses order access');
select lives_ok($$select billtest.staff('close')$$,'empty visit can close without fabricated payments');
select is((select count(*)::int from public.payments),1,'empty closure generates no new payment');
select lives_ok($$select public.visit_workflow('open',p_table=>'10000000-0000-4000-8000-000000000020',p_actor=>'10000000-0000-4000-8000-000000000002')$$,'third party starts clean');
select lives_ok($$select public.visit_workflow('join',p_tab=>billtest.tab(),p_secret_hash=>repeat('7',64),p_data=>jsonb_build_object('name','Dana','receiptHash',repeat('8',64)))$$,'third party session');
update mezza_private.visit_sessions set expires_at=now()-interval '1 second' where secret_hash=repeat('7',64);
select throws_ok($$select billtest.guest('snapshot','{}',repeat('7',64))$$,'42501','session_expired','four-hour server expiry blocks reads');
update mezza_private.visit_receipts set expires_at=now()-interval '1 second';
select is(jsonb_array_length(public.visit_private_receipts(repeat('c',64),'10000000-0000-4000-8000-000000000020')),0,'expired receipt access is denied');
select throws_ok($$update public.payments set amount_cents=1$$,'P0001','immutable_payment','paid monetary facts cannot be edited through legacy staff writes');
select throws_ok($$update public.payments set status='refunded'$$,'P0001','refund_required','refund status cannot be fabricated without linked refund');
select throws_ok($$select billtest.staff('writeoff',jsonb_build_object('id',gen_random_uuid(),'reason','test reason'))$$,'42501','forbidden','server cannot write off a balance');

update mezza_private.visit_sessions set expires_at=now()+interval '4 hours' where secret_hash=repeat('7',64);
select lives_ok($$select billtest.guest('draft','{"version":0,"lines":[{"itemId":"10000000-0000-4000-8000-000000000040","qty":1,"optionIds":[]}]}',repeat('7',64))$$,'restored session can save cart');
select lives_ok($$select billtest.guest('submit','{"id":"10000000-0000-4000-8000-000000000080","version":1}',repeat('7',64))$$,'partial-payment test submission');
select lives_ok($$select billtest.staff('accept','{"id":"10000000-0000-4000-8000-000000000080"}')$$,'accept partial-payment bill');
select lives_ok($$select billtest.staff('add_person','{"name":"Eli"}')$$,'staff adds a diner without a phone');
create function billtest.split_partial() returns jsonb language sql as $$
 select jsonb_build_object('revision',t.bill_revision,'mode','items','ackDrafts',true,'portions',jsonb_build_array(
  jsonb_build_object('participantId',billtest.pid('Dana'),'subtotalCents',501,'stateCents',53,'municipalCents',5,'lines',jsonb_build_array(jsonb_build_object('lineId',i.id,'unit',0,'name','Plato','cents',501))),
  jsonb_build_object('participantId',billtest.pid('Eli'),'subtotalCents',500,'stateCents',52,'municipalCents',5,'lines',jsonb_build_array(jsonb_build_object('lineId',i.id,'unit',0,'name','Plato','cents',500)))))
 from public.tabs t join public.orders o on o.tab_id=t.id join public.order_items i on i.order_id=o.id where t.id=billtest.tab()
$$;
select lives_ok($$select billtest.staff('freeze',billtest.split_partial())$$,'shared item allocated to phone and manual diners');
select lives_ok($$select billtest.staff('cash',jsonb_build_object('portionIds',(select jsonb_agg(id) from mezza_private.bill_portions where tab_id=billtest.tab() and participant_id=billtest.pid('Dana')),'payerId',billtest.pid('Dana'),'key','partial-cash-1','tipCents',25,'tenderCents',600,'receiptHash',repeat('9',64)))$$,'one portion paid with explicit tip');
select throws_ok($$select billtest.staff('reopen')$$,'P0001','cannot_reopen','partial payment locks the split permanently');
select throws_ok($$select billtest.staff('close')$$,'P0001','unsettled_bill','partial payment cannot close outstanding balance');
select throws_ok($$select billtest.staff('writeoff',jsonb_build_object('id',(select id from mezza_private.bill_portions where tab_id=billtest.tab() and participant_id=billtest.pid('Eli')),'reason','guest left'))$$,'42501','forbidden','server cannot resolve abandoned balance');
select lives_ok($$select billtest.staff('writeoff',jsonb_build_object('id',(select id from mezza_private.bill_portions where tab_id=billtest.tab() and participant_id=billtest.pid('Eli')),'reason','guest left'),'10000000-0000-4000-8000-000000000001')$$,'manager explicitly resolves abandoned balance');
select is((public.visit_financial_summary('10000000-0000-4000-8000-000000000010','10000000-0000-4000-8000-000000000001',current_date-1,current_date+1)->>'writtenOffCents')::int,557,'report distinguishes unpaid writeoff from cash collection');
select is((select count(*)::int from public.payments),2,'writeoff creates no fictitious payment');
select lives_ok($$select billtest.staff('close')$$,'paid and manager-resolved portions permit closure');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select lives_ok($$select public.record_refund((select id from public.payments where idempotency_key='partial-cash-1'),584,'paid refund correction')$$,'manager refunds full actual cash including explicit tip');
set local role service_role;
select is((select status::text from public.payments where idempotency_key='partial-cash-1'),'refunded','linked refund changes payment disposition');
select is((select status from mezza_private.bill_portions where payment_id=(select id from public.payments where idempotency_key='partial-cash-1')),'paid','refund does not silently reopen someone else liability');
select is((public.visit_private_receipts(repeat('8',64),'10000000-0000-4000-8000-000000000020')->0->>'refundCents')::int,584,'payer receipt reports linked refund separately');
select ok(public.visit_rate_limit('test-counter',1,60),'first shared limit request allowed');
select ok(not public.visit_rate_limit('test-counter',1,60),'second request blocked by shared counter');
select * from finish();
rollback;
